"""Source of truth for ingredient intelligence. Run to regenerate ingredient_mappings.json.
Format per row: standard_name, category, allergen_group (comma-separated or ""), intolerance_groups, dietary_tags, aliases
"""
import json, os

M = []
def add(name, cat, allergen, intol, tags, aliases):
    M.append({"standard_name": name, "category": cat, "allergen_group": allergen or None,
              "intolerance_group": intol, "dietary_tags": tags,
              "aliases": sorted(set([name.lower()] + [a.lower() for a in aliases]))})

